  }
  return max;
}"}

{"explanation":"Iterate over the array without modifying it and count elements that are strictly the boolean true (using ===), so truthy values like 1, 'true', or non-empty objects are not counted. Non-array input returns 0 to be safe. Using a simple loop (rather than filter) avoids creating intermediate arrays and handles sparse arrays by counting only present true entries via index access of existing elements.","code":"function solve(arr) {
  if (!Array.isArray(arr)) return 0;
  let count = 0;
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === true) count++;
  }
  return count;
}"}

