}"}

{"explanation":"Return a new array without mutating the input. Empty arrays return a copy. Normalize k with ((k % n) + n) % n so negative k and k larger than n work (negative k rotates left). Non-integer k is truncated via Math.trunc. The result is arr.slice(n - r).concat(arr.slice(0, n - r)), where r is the normalized shift; when r is 0 this yields a plain copy.","code":"function solve(arr, k) {
  const n = arr.length;
  if (n === 0) return [];
  const kk = Math.trunc(Number(k)) || 0;
  const r = ((kk % n) + n) % n;
  if (r === 0) return arr.slice();
  return arr.slice(n - r).concat(arr.slice(0, n - r));
}"}

{"explanation":"Build a Set from the second array for O(1) membership checks, then filter the first array, keeping elements not in the set. filter returns a new array so inputs are not mutated, and order and duplicates of the first array are preserved. Set uses SameValueZero, so NaN is matched correctly and 0/-0 are treated as equal.","code":"function solve(a, b) {
  const exclude = new Set(b);
  return a.filter((x) => !exclude.has(x));
}"}

{"code":"function solve(arr) {
  const s = [...arr].sort((a, b) => a - b);
  const m = s.length >> 1;
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
}"}

{"explanation":"Return [] for an empty matrix (or one whose rows are empty, since transposing a 0-column matrix has no rows to produce). Otherwise build a new matrix with Array.from where result[j][i] = matrix[i][j], iterating over the column count taken from the first row. New arrays are created and the input is never modified.","code":"function solve(matrix) {
  if (!Array.isArray(matrix) || matrix.length === 0) return [];
  const rows = matrix.length;
  const cols = matrix[0].length;
  if (cols === 0) return [];
  return Array.from({ length: cols }, (_, j) =>
    Array.from({ length: rows }, (_, i) => matrix[i][j])
  );
}"}

{"explanation":"Split each version string on '.', convert each component to BigInt (so very large components and leading zeros compare correctly numerically), and walk up to the longer length, treating missing components as 0n. Return -1 or 1 at the first differing component, else 0. Inputs are only read, never mutated, since split/map create new arrays.","code":"function solve(a, b) {
  const pa = String(a).split('.').map((s) => BigInt(s));
  const pb = String(b).split('.').map((s) => BigInt(s));
  const n = Math.max(pa.length, pb.length);
  for (let i = 0; i < n; i++) {
    const x = i < pa.length ? pa[i] : 0n;
    const y = i < pb.length ? pb[i] : 0n;
    if (x < y) return -1;
    if (x > y) return 1;
  }
  return 0;
}"}

{"code":"function solve(edges) {
  const adj = new Map(), indeg = new Map();
  const add = n => { if (!adj.has(n)) { adj.set(n, new Set()); indeg.set(n, 0); } };
  for (const [a, b] of edges || []) {
    add(a); add(b);
    if (!adj.get(a).has(b)) { adj.get(a).add(b); indeg.set(b, indeg.get(b) + 1); }
  }
  const ready = [...indeg].filter(([, d]) => !d).map(([n]) => n);
  const out = [];
  while (ready.length) {
    ready.sort();
    const n = ready.shift();
    out.push(n);
    for (const m of adj.get(n)) {
      indeg.set(m, indeg.get(m) - 1);
      if (!indeg.get(m)) ready.push(m);
    }
  }
  return out.length === adj.size ? out : null;
}"}

{"explanation":"Nearest-rank percentile: rank = ceil(p/100 * n), 1-indexed, clamped to [1, n]. The input is copied with slice() before sorting so it is not mutated, and sorted numerically with (a,b)=>a-b because the default sort is lexicographic. To avoid floating-point error in 0.95*n (e.g. n=20 giving 19.000000000000004 and ceil returning 20), the rank is computed with integers: ceil(95*n/100) = Math.floor((95*n + 99)/100). The result is the sorted element at index rank-1.","code":"function solve(arr) {
  const sorted = arr.slice().sort((a, b) => a - b);
  const n = sorted.length;
  let rank = Math.floor((95 * n + 99) / 100);
  if (rank < 1) rank = 1;
  if (rank > n) rank = n;
  return sorted[rank - 1];
}"}

{"code":"function solve(a, b) {
  a = String(a ?? '');
  b = String(b ?? '');
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost);
    }
    prev = cur;
  }
  return prev[b.length];
}"}

{"explanation":"Use a greedy approach over a fixed table of value/symbol pairs, including the subtractive forms (900, 400, 90, 40, 9, 4), ordered from largest to smallest. For each pair, append the symbol while the remaining number is at least its value and subtract that value. The input is a primitive number so nothing is mutated; a local copy is decremented. Inputs outside the integer range 1..3999 throw a RangeError.","code":"function solve(num) {
  if (typeof num !== 'number' || !Number.isInteger(num) || num < 1 || num > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999');
  }
  const table = [
    [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
    [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
    [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']
  ];
  let remaining = num;
  let result = '';
  for (const [value, symbol] of table) {
    while (remaining >= value) {
      result += symbol;
      remaining -= value;
    }
  }
  return result;
}"}

{"code":"function solve(arr, k) {
  const n = arr.length;
  if (n === 0) return [];
  const s = ((Math.trunc(k) % n) + n) % n;
  return s === 0 ? arr.slice() : arr.slice(-s).concat(arr.slice(0, n - s));
}"}

