{"explanation":"Strings are immutable in JS, so no input is mutated. The input is coerced to a string, lowercased, and every run of characters outside [a-z0-9] is replaced with a single hyphen. Because text is lowercased first, uppercase ASCII letters are kept as lowercase. Non-ASCII characters count as non-alphanumeric and are collapsed into hyphens. Leading and trailing hyphens are then trimmed with a regex. Null or undefined input returns an empty string.","code":"function solve(input) {
  if (input === null || input === undefined) return '';
  return String(input)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}"}

{"explanation":"Uses BigInt with fast doubling (O(log n)) so large n stays exact instead of losing precision past F78. For n, compute pair (F(k), F(k+1)) recursively via F(2k)=F(k)*(2*F(k+1)-F(k)) and F(2k+1)=F(k)^2+F(k+1)^2. The input is a number or BigInt and is only read, never mutated. Invalid input (negative, non-integer) throws a RangeError. Returns a BigInt.","code":"function solve(n) {
  if (typeof n === 'bigint') {
    if (n < 0n) throw new RangeError('n must be >= 0');
  } else if (!Number.isInteger(n) || n < 0) {
    throw new RangeError('n must be a non-negative integer');
  }
  const N = BigInt(n);
  function fd(k) {
    if (k === 0n) return [0n, 1n];
    const [a, b] = fd(k >> 1n);
    const c = a * (2n * b - a);
    const d = a * a + b * b;
    return (k & 1n) === 0n ? [c, d] : [d, c + d];
  }
  return fd(N)[0];
}"}

{"explanation":"Iterate the string with for...of, which yields whole Unicode code points (surrogate pairs stay intact) rather than UTF-16 units. Keep the current character and a running count; when the next code point differs, push [char, count] and start a new run. Push the final run after the loop. Empty string returns []. The input is a primitive string and is never mutated; a new array is returned. Non-string input is coerced via String().","code":"function solve(str) {
  const s = String(str);
  const result = [];
  let current = null;
  let count = 0;
  for (const ch of s) {
    if (count > 0 && ch === current) {
      count++;
    } else {
      if (count > 0) result.push([current, count]);
      current = ch;
      count = 1;
    }
  }
  if (count > 0) result.push([current, count]);
  return result;
}"}

{"code":"function solve(a, b) {
  const count = (s) => {
    const c = new Array(26).fill(0);
    for (const ch of String(s)) {
      const i = ch.toLowerCase().charCodeAt(0) - 97;
      if (ch.length === 1 && i >= 0 && i < 26) c[i]++;
    }
    return c;
  };
  const x = count(a), y = count(b);
  return x.every((n, i) => n === y[i]);
}"}

{"explanation":"Strings are immutable in JS so inputs are never mutated. Convert the input to a string, lowercase it (toLowerCase on ASCII letters is safe; non-ASCII letters are treated as non-alphanumeric since only [a-z0-9] is kept after lowercasing), replace each run of characters outside [a-z0-9] with a single hyphen, then trim leading and trailing hyphens. Using /[^a-z0-9]+/g collapses runs, and /^-+|-+$/g trims edges. Non-string input is coerced via String, with null/undefined yielding an empty string. Note: toLowerCase could map some non-ASCII characters (e.g. the Kelvin sign U+212A) to ASCII 'k', so lowercasing is restricted to ASCII A-Z explicitly to keep behavior strictly ASCII.","code":"function solve(text) {
  const s = text == null ? '' : String(text);
  return s
    .replace(/[A-Z]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 32))
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}"}

{"code":"function solve(arr, target) {
  let lo = 0, hi = arr.length;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (arr[mid] < target) lo = mid + 1;
    else hi = mid;
  }
  return lo < arr.length && arr[lo] === target ? lo : -1;
}"}

{"explanation":"Standard base64 uses '+' and '/', and may end with '=' padding. base64url uses '-' and '_' instead, and the padding is dropped. The function replaces '+' with '-' and '/' with '_' using global regexes, then strips trailing '=' characters. Strings are immutable in JavaScript, so the input is never mutated. Whitespace is not handled, since the input is assumed to be a valid standard base64 string.","code":"function solve(input) {
  return String(input)
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}"}

{"code":"function solve(input) {
  const map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  return String(input ?? '').replace(/[&<>"']/g, c => map[c]);
}"}

{"code":"function solve(s) {
  const pairs = { ')': '(', ']': '[', '}': '{' };
  const open = new Set(Object.values(pairs));
  const stack = [];
  for (const ch of String(s)) {
    if (open.has(ch)) stack.push(ch);
    else if (ch in pairs && stack.pop() !== pairs[ch]) return false;
  }
  return stack.length === 0;
}"}

