}"}

{"code":"function solve(s) {
  const str = String(s);
  let bytes = 0;
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    if (c < 0x80) bytes += 1;
    else if (c < 0x800) bytes += 2;
    else if (c >= 0xD800 && c <= 0xDBFF && i + 1 < str.length) {
      const n = str.charCodeAt(i + 1);
      if (n >= 0xDC00 && n <= 0xDFFF) { bytes += 4; i++; }
      else bytes += 3;
    } else bytes += 3;
  }
  return bytes;
}"}

{"code":"function solve(a, b) {
  const x = String(a).split('.').map(Number);
  const y = String(b).split('.').map(Number);
  const n = Math.max(x.length, y.length);
  for (let i = 0; i < n; i++) {
    const p = x[i] || 0;
    const q = y[i] || 0;
    if (p !== q) return p < q ? -1 : 1;
  }
  return 0;
}"}

{"code":"function solve(intervals) {
  const sorted = intervals.map(([s, e]) => [s, e]).sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const out = [];
  for (const [s, e] of sorted) {
    const last = out[out.length - 1];
    if (last && s <= last[1]) last[1] = Math.max(last[1], e);
    else out.push([s, e]);
  }
  return out;
}"}

{"code":"function solve(input) {
  const out = {};
  let s = String(input ?? '').split('#')[0];
  const q = s.indexOf('?'), e = s.indexOf('=');
  if (q >= 0 && (e < 0 || q < e)) s = s.slice(q + 1);
  const dec = t => {
    t = t.replace(/\+/g, ' ');
    try { return decodeURIComponent(t); } catch { return t; }
  };
  for (const part of s.split('&')) {
    if (!part) continue;
    const i = part.indexOf('=');
    const k = dec(i < 0 ? part : part.slice(0, i));
    const v = i < 0 ? '' : dec(part.slice(i + 1));
    if (Object.prototype.hasOwnProperty.call(out, k)) out[k].push(v);
    else Object.defineProperty(out, k, { value: [v], enumerable: true, writable: true, configurable: true });
  }
  return out;
}"}

{"code":"function solve(s) {
  if (typeof s !== 'string' || !/^\d+$/.test(s)) return false;
  let sum = 0;
  for (let i = 0; i < s.length; i++) {
    let d = Number(s[s.length - 1 - i]);
    if (i % 2 === 1) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
  }
  return sum % 10 === 0;
}"}

