  const sieve = new Uint8Array(m + 1);
  const primes = [];
  for (let i = 2; i <= m; i++) {
    if (sieve[i]) continue;
    primes.push(i);
    for (let j = i * i; j <= m; j += i) sieve[j] = 1;
  }
  return primes;
}"}

{"explanation":"solve(str) iterates over the string by UTF-16 code units and sums the UTF-8 byte length of each code point: 1 byte for U+0000–U+007F, 2 for up to U+07FF, 3 for up to U+FFFF, and 4 for supplementary code points. A valid surrogate pair (high 0xD800–0xDBFF followed by low 0xDC00–0xDFFF) is counted as one code point of 4 bytes and both units are consumed. A lone surrogate is counted as 3 bytes, matching the U+FFFD replacement character that TextEncoder would emit. Non-string input is coerced with String(). The input is only read, never mutated, and Buffer is not used.","code":"function solve(input) {
  const s = typeof input === 'string' ? input : String(input);
  let bytes = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c < 0x80) {
      bytes += 1;
    } else if (c < 0x800) {
      bytes += 2;
    } else if (c >= 0xD800 && c <= 0xDBFF && i + 1 < s.length) {
      const next = s.charCodeAt(i + 1);
      if (next >= 0xDC00 && next <= 0xDFFF) {
        bytes += 4;
        i++;
      } else {
        bytes += 3;
      }
    } else {
      bytes += 3;
    }
  }
  return bytes;
}"}

{"code":"function solve(arr) {
