{"code":"function solve(edges) {
  const adj = new Map();
  const indeg = new Map();
  const add = n => {
    if (!adj.has(n)) {
      adj.set(n, new Set());
      indeg.set(n, 0);
    }
  };
  for (const [a, b] of edges) {
    add(a);
    add(b);
    if (!adj.get(a).has(b)) {
      adj.get(a).add(b);
      indeg.set(b, indeg.get(b) + 1);
    }
  }
  const ready = [...indeg].filter(([, d]) => d === 0).map(([n]) => n).sort();
  const out = [];
  while (ready.length) {
    const n = ready.shift();
    out.push(n);
    for (const m of adj.get(n)) {
      indeg.set(m, indeg.get(m) - 1);
      if (indeg.get(m) === 0) ready.push(m);
    }
    ready.sort();
  }
  return out.length === adj.size ? out : null;
}"}

{"code":"function solve(row) {
