    } else if (c === '"') {
      quoted = true;
    } else if (c === ',') {
      out.push(field);
      field = '';
    } else {
      field += c;
    }
  }
  out.push(field);
  return out;
}"}

{"explanation":"Copy each interval into a new array so the input is never mutated, then sort the copies by start (ties broken by end). Sweep once, keeping a result list. If the next interval's start is <= the last merged interval's end, the two overlap or touch (closed intervals), so extend the last end to the max of both ends. Otherwise push a new interval. Non-array or empty input returns []. Intervals that only touch at a point, like [1,2] and [2,3], are merged into [1,3]. Pairs that merely sit side by side on integers, like [1,2] and [3,4], are not merged.","code":"function solve(intervals) {
  if (!Array.isArray(intervals)) return [];
  const sorted = intervals
    .map(function (iv) { return [iv[0], iv[1]]; })
    .sort(function (a, b) { return a[0] - b[0] || a[1] - b[1]; });
  const result = [];
  for (const cur of sorted) {
    const last = result[result.length - 1];
    if (last && cur[0] <= last[1]) {
      if (cur[1] > last[1]) last[1] = cur[1];
    } else {
      result.push([cur[0], cur[1]]);
    }
  }
  return result;
}"}

{"explanation":"Build a Set from the second array for O(1) membership checks, then filter the first array, keeping elements not in the set. filter returns a new array, so inputs are not mutated, and original order and duplicates are preserved. Set uses SameValueZero, so NaN is matched correctly and 0/-0 are treated as equal.","code":"function solve(a, b) {
  const exclude = new Set(b);
  return a.filter((x) => !exclude.has(x));
}"}

{"explanation":"Iterate once over the input array, tracking seen strings in a Set. Push a string to the result only if it has not been seen, which preserves first-occurrence order. A new array is built and the input is never modified. Runs in O(n) time. Set uses SameValueZero equality, which is exact matching for strings, so case and whitespace differences are treated as distinct values.","code":"function solve(arr) {
  const seen = new Set();
  const result = [];
  for (const item of arr) {
    if (!seen.has(item)) {
      seen.add(item);
      result.push(item);
    }
  }
  return result;
}"}

