  return String(input).replace(/[&<>"']/g, (ch) => map[ch]);
}"}

{"explanation":"The function rejects non-strings, then splits on '.' and requires exactly four parts. Each part must match /^(0|[1-9]\d{0,2})$/, which allows a single '0' or a number with no leading zero and at most three digits, and it excludes empty parts, signs, whitespace, and non-ASCII digits (\d without the u flag is ASCII-only). Each part is then converted to a number and checked to be <= 255. The input is a primitive string and is never mutated.","code":"function solve(input) {
  if (typeof input !== 'string') return false;
  const parts = input.split('.');
  if (parts.length !== 4) return false;
  for (const part of parts) {
    if (!/^(0|[1-9][0-9]{0,2})$/.test(part)) return false;
    if (Number(part) > 255) return false;
  }
  return true;
}"}

{"explanation":"Split each version string on '.', then compare component by component up to the longer length. A missing component counts as '0'. Each component is compared as a digit string with leading zeros stripped (a longer string is larger, and equal lengths compare lexicographically). This is exact for arbitrarily large integers, where Number parsing would lose precision. The function returns -1, 0 or 1 on the first difference, and 0 if none is found. The inputs are only read, never mutated.","code":"function solve(a, b) {
  const pa = String(a).split('.');
  const pb = String(b).split('.');
  const n = Math.max(pa.length, pb.length);
  const norm = (s) => {
    if (s === undefined) return '0';
    const t = s.replace(/^0+/, '');
    return t === '' ? '0' : t;
  };
  for (let i = 0; i < n; i++) {
    const x = norm(pa[i]);
    const y = norm(pb[i]);
    if (x.length !== y.length) return x.length > y.length ? 1 : -1;
    if (x !== y) return x > y ? 1 : -1;
  }
  return 0;
}"}

{"explanation":"Reject non-strings. Split on '.', require exactly 4 parts. Each part must match /^(0|[1-9][0-9]{0,2})$/ (digits only, no leading zeros except a lone '0', max 3 digits), then check numeric value <= 255. The regex rejects empty parts, signs, whitespace, and non-ASCII digits. Input is never mutated.","code":"function solve(s) {
