}"}

{"explanation":"Strings are never mutated (JS strings are immutable, and we only build new values). For each string, iterate characters, keep only ASCII letters A-Z/a-z (nonletters ignored), lowercase them, and count occurrences in a 26-slot array. Two strings are anagrams if their count arrays are equal. Using char codes avoids locale/Unicode issues from regex or toLowerCase on non-ASCII characters. Two strings with no letters are considered anagrams (both empty multisets). Non-string inputs are coerced via String().","code":"function solve(a, b) {
  function counts(s) {
    const c = new Array(26).fill(0);
    const str = String(s);
    for (let i = 0; i < str.length; i++) {
      let code = str.charCodeAt(i);
      if (code >= 65 && code <= 90) code += 32;
      if (code >= 97 && code <= 122) c[code - 97]++;
    }
    return c;
  }
  const x = counts(a);
  const y = counts(b);
  for (let i = 0; i < 26; i++) {
    if (x[i] !== y[i]) return false;
  }
  return true;
}"}

{"explanation":"Use a stack. Iterate over the string's characters; push each opening bracket's expected closing counterpart onto the stack. On a closing bracket, the stack must be non-empty and its top must equal that character, otherwise return false (mismatch or unmatched closer). All other characters are ignored. At the end the string is balanced only if the stack is empty (no unclosed openers). The input string is only read, never mutated, and non-string input is coerced via String() safely.","code":"function solve(input) {
  const s = String(input);
  const pairs = { '(': ')', '[': ']', '{': '}' };
  const closers = new Set([')', ']', '}']);
  const stack = [];
  for (const ch of s) {
    if (Object.prototype.hasOwnProperty.call(pairs, ch)) {
      stack.push(pairs[ch]);
    } else if (closers.has(ch)) {
      if (stack.length === 0 || stack.pop() !== ch) {
        return false;
      }
    }
  }
  return stack.length === 0;
}"}

{"explanation":"Iterate over the input once, tracking seen strings in a Set. Push a string to the result only if it has not been seen, which preserves first-occurrence order. The input array is only read, never modified, and a new array is returned. Set uses SameValueZero, so exact string equality applies (case-sensitive). Runs in O(n) time.","code":"function solve(arr) {
  const seen = new Set();
  const result = [];
  for (const s of arr) {
    if (!seen.has(s)) {
      seen.add(s);
      result.push(s);
    }
  }
  return result;
}"}

{"explanation":"Build a deduplicated adjacency map and in-degree counts from the edges, creating fresh structures so the input is never mutated. Kahn's algorithm uses a binary min-heap of zero-in-degree nodes, so the smallest available node (by plain string comparison) is always taken next. Duplicate edges are counted once so in-degrees stay correct. A self-loop or any cycle leaves some nodes with nonzero in-degree, so the output is shorter than the node count and the function returns null. Empty edges return an empty array.","code":"function solve(edges) {
  const adj = new Map();
  const indeg = new Map();
  const add = (n) => {
    if (!adj.has(n)) {
      adj.set(n, new Set());
      indeg.set(n, 0);
    }
  };
  for (const [a, b] of edges) {
    add(a);
    add(b);
    if (!adj.get(a).has(b)) {
      adj.get(a).add(b);
      indeg.set(b, indeg.get(b) + 1);
    }
  }
  const h = [];
  const push = (x) => {
    let i = h.push(x) - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (h[p] <= h[i]) break;
      [h[p], h[i]] = [h[i], h[p]];
      i = p;
    }
  };
  const pop = () => {
    const top = h[0];
    const last = h.pop();
    if (h.length) {
      h[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let m = i;
        if (l < h.length && h[l] < h[m]) m = l;
        if (r < h.length && h[r] < h[m]) m = r;
        if (m === i) break;
        [h[m], h[i]] = [h[i], h[m]];
        i = m;
      }
    }
    return top;
  };
  for (const [n, d] of indeg) if (d === 0) push(n);
  const out = [];
  while (h.length) {
    const n = pop();
    out.push(n);
    for (const m of adj.get(n)) {
      const d = indeg.get(m) - 1;
      indeg.set(m, d);
      if (d === 0) push(m);
    }
  }
  return out.length === adj.size ? out : null;
}"}

{"code":"function solve(n) {
  const map = [[1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'], [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'], [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']];
  if (!Number.isInteger(n) || n < 1 || n > 3999) throw new RangeError('n must be an integer from 1 to 3999');
  let result = '';
  for (const [value, symbol] of map) {
