    } else bytes += 3;
  }
  return bytes;
}"}

{"explanation":"Single-pass state machine over the characters of the row. Inside quotes, a doubled quote ("") emits a literal quote, a single quote ends the quoted section, and commas are kept as data. Outside quotes, a comma ends the field, a quote begins a quoted section, and other characters are appended. The final field is pushed at the end, so an empty string yields [''] and a trailing comma yields a trailing empty field. The input string is never mutated (strings are immutable and a new array is returned). Non-string input is coerced via String, and null/undefined gives [''].","code":"function solve(row) {
  const s = row == null ? '' : String(row);
  const fields = [];
  let cur = '';
  let inQuotes = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (inQuotes) {
      if (ch === '"') {
        if (s[i + 1] === '"') {
          cur += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        cur += ch;
      }
    } else if (ch === ',') {
      fields.push(cur);
      cur = '';
    } else if (ch === '"') {
      inQuotes = true;
    } else {
      cur += ch;
    }
  }
  fields.push(cur);
  return fields;
}"}

